import type { LeagueConfig } from "../config/leagues.ts";
import { PRIOR_SEASONS } from "../data/priors/index.ts";
import {
  DIXON_COLES,
  DOMESTIC_PRIOR_GAMES,
  matchParamOptions,
  NO_DATA_PRIOR,
  ratingHalfLife,
  ratingXgWeight,
  TEAM_HOME_ADVANTAGE,
  type MatchParams,
  type ModelOptions,
  type TeamStrength,
} from "../engine/ratings.ts";

export type { MatchParams };

/**
 * One season's priors by league code (generated by scripts/build-priors.ts,
 * see src/data/priors): each club's starting [attack, defence] by ESPN id
 * (relative to the league average; defence above 1 concedes more), the
 * league's Dixon–Coles rho, and returning clubs' home/away splits.
 */
export type PriorSeason = Readonly<
  Record<
    string,
    {
      readonly rho: number;
      readonly clubs: Readonly<Record<string, readonly [number, number]>>;
      readonly home: Readonly<Record<string, number>>;
    }
  >
>;

/** The newest season with a priors file. */
export function latestPriorYear(seasons: Readonly<Record<number, PriorSeason>> = PRIOR_SEASONS): number | undefined {
  const years = Object.keys(seasons).map(Number);
  return years.length ? Math.max(...years) : undefined;
}

const warned = new Set<string>();

/**
 * A domestic league's starting ratings for the season starting in `year`:
 * that season's file, else the latest earlier one, with a warning (rerun
 * scripts/build-priors.ts for the new season). A club the file doesn't list
 * starts from NO_DATA_PRIOR, below average (see `domesticModelOptions` and
 * the model's `missingPrior`). Undefined for sample data, whose clubs aren't real.
 */
export function domesticPriors(code: string, year: number | undefined, seasons: Readonly<Record<number, PriorSeason>> = PRIOR_SEASONS): Record<number, TeamStrength> | undefined {
  if (year === undefined || process.env.FOOTSIMU_SAMPLE_DATA === "1") return undefined;
  const known = Object.keys(seasons)
    .map(Number)
    .filter((y) => y <= year && seasons[y]?.[code])
    .sort((a, b) => b - a)[0];
  const table = known === undefined ? undefined : seasons[known]![code]?.clubs;
  if (!table) return undefined;
  if (known !== year && !warned.has(`${code}:${year}`)) {
    warned.add(`${code}:${year}`);
    console.warn(`${code}: no starting ratings for the ${year} season, using ${known}'s (run \`npm run priors -- ${year}\` to rebuild them)`);
  }
  return Object.fromEntries(Object.entries(table).map(([id, [attack, defence]]) => [Number(id), { attack, defence }]));
}

/** The league's rho and clubs' home splits, from the same season's file as its priors (none for sample data). */
export function domesticMatchParams(code: string, year: number | undefined, seasons: Readonly<Record<number, PriorSeason>> = PRIOR_SEASONS): MatchParams {
  if (year === undefined || process.env.FOOTSIMU_SAMPLE_DATA === "1") return {};
  const known = Object.keys(seasons)
    .map(Number)
    .filter((y) => y <= year && seasons[y]?.[code])
    .sort((a, b) => b - a)[0];
  const league = known === undefined ? undefined : seasons[known]![code];
  if (!league) return {};
  return {
    ...(DIXON_COLES ? { rho: league.rho } : {}),
    ...(TEAM_HOME_ADVANTAGE ? { homeFactor: Object.fromEntries(Object.entries(league.home).map(([id, k]) => [Number(id), k])) } : {}),
  };
}

/**
 * A league's match parameters (domesticMatchParams) and, when its ratings use
 * xG (LeagueConfig.ratingXgWeight), its played games' xG and the weight they
 * get; leagues without it get exactly domesticMatchParams.
 */
export function leagueMatchParams(league: LeagueConfig, year: number | undefined, xg?: Readonly<Record<number, readonly [number, number]>>): MatchParams {
  const weight = ratingXgWeight(league);
  return { ...domesticMatchParams(league.code, year), ...(xg && weight > 0 ? { xg, xgWeight: weight } : {}) };
}

/** How much this season's form weighs against the prior in a domestic league. */
export function domesticPriorGames(league: LeagueConfig): number {
  return league.ratingPriorGames ?? DOMESTIC_PRIOR_GAMES;
}

/** Rating options for a domestic league's own model (its page, and its clubs elsewhere: cups, continental). */
export function domesticModelOptions(league: LeagueConfig, year: number | undefined, xg?: Readonly<Record<number, readonly [number, number]>>): ModelOptions {
  const priors = domesticPriors(league.code, year);
  return {
    priorGames: domesticPriorGames(league),
    halfLife: ratingHalfLife(league),
    ...matchParamOptions(leagueMatchParams(league, year, xg)),
    ...(priors ? { priorStrengths: new Map(Object.entries(priors).map(([id, s]) => [Number(id), s])), missingPrior: NO_DATA_PRIOR } : {}),
  };
}
